const j = $json;
let handle = "";
const keys = ["Instagram","instagram","IG","Insta","instagram_url","instagramUrl","instagramUsername"];
for (const k of keys) { if (j[k]) { handle = String(j[k]); break; } }
if (!handle) { for (const [k, v] of Object.entries(j)) { if (typeof v === "string" && /instagram\.com/i.test(v)) { handle = v; break; } } }
if (handle) { const m = handle.match(/instagram\.com\/([A-Za-z0-9_.]+)/i); if (m) handle = m[1]; handle = handle.replace(/^@/, "").replace(/\/$/, "").trim(); }
const businessName = j["Nom"] || j["Titre"] || j["Name"] || j["businessName"] || "";
const adresse = j["Adresse"] || j["adresse"] || j["Address"] || "";
const siteWeb = j["Site Web"] || j["SiteWeb"] || j["Website"] || j["site"] || "";
const email = (j["Email"] || j["email"] || j["E-mail"] || j["Mail"] || "").toString().trim();
return { json: { row_number: j.row_number, businessName: businessName, adresse: adresse, siteWeb: siteWeb, igHandleFromSheet: handle, email: email, FeedStatus: j["FeedStatus"] || "" } };

// Deterministic Instagram-handle discovery. NO LLM.
// Input = raw HTML of the lead's own website (HTTP node, responseFormat=text -> $json.data).
// A business almost always links its own Instagram from its own site.
// Guard: many 'Site Web' values in Sortie2 are third-party aggregators (bluepillow,
// booking, tripadvisor...). Their pages link THEIR OWN Instagram, so we only keep a
// handle that is plausibly related to the business name, otherwise we return nothing
// and let the Apify name-search decide.
const RESERVED = new Set(["p","reel","reels","explore","stories","tv","s","accounts","about","directory","legal","web","developer","help","privacy","terms","download","instagram"]);
const AGGREGATORS = ["bluepillow","booking","airbnb","expedia","tripadvisor","thefork","lafourchette","ubereats","deliveroo","justeat","yelp","pagesjaunes","petitfute","google","facebook","instagram","wix","wordpress","shopify","squarespace","hostelworld","trivago","agoda","vrbo","abritel"];
const STOP = new Set(["le","la","les","au","aux","du","de","des","chez","une","un","the","and","for","with","restaurant","restaurants","brasserie","pizzeria","boulangerie","patisserie","snack","villa","hotel","room","rooms","bedroom","apartment","appartement","studio","maison","house","lodge","gite","chambre","chambres","resort","guesthouse"]);

function clean(h){ return (h||"").toString().trim().replace(/^@/,"").replace(/^https?:\/\/(www\.)?instagram\.com\//i,"").replace(/[\/?#].*$/,"").replace(/\/$/,"").trim(); }
function norm(s){ return (s||"").toString().toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9]/g,""); }
function tokens(s){
  return (s||"").toString().toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"")
    .split(/[^a-z0-9]+/).filter(t => t.length >= 4 && !STOP.has(t));
}

let lead;
try { lead = $("Extract Lead").item.json; } catch (e) { lead = $("Extract Lead").first().json; }

const src = $json || {};
let raw = "";
if (typeof src.data === "string") raw = src.data;
else if (typeof src.body === "string") raw = src.body;
else raw = JSON.stringify(src);

const siteWeb = (lead.siteWeb || "").toString();
const siteHost = norm((siteWeb.match(/^(?:https?:\/\/)?(?:www\.)?([^\/?#]+)/i) || ["",""])[1]);
const isAggregator = AGGREGATORS.some(a => siteHost.indexOf(a) !== -1);

let siteHandle = "";
if (!isAggregator) {
  const counts = {};
  const re = /instagram\.com\/([A-Za-z0-9_.]{2,30})/ig;
  let m;
  while ((m = re.exec(raw))) {
    const c = clean(m[1]);
    if (!c) continue;
    const lc = c.toLowerCase();
    if (RESERVED.has(lc)) continue;
    if (AGGREGATORS.some(a => lc.indexOf(a) !== -1)) continue;
    counts[c] = (counts[c] || 0) + 1;
  }
  const ranked = Object.keys(counts).sort((a,b) => counts[b] - counts[a]);
  const candidate = ranked[0] || "";
  const bizTokens = tokens(lead.businessName);
  const nCand = norm(candidate);
  const related = bizTokens.length > 0 && bizTokens.some(t => nCand.indexOf(t) !== -1 || siteHost.indexOf(t) !== -1);
  siteHandle = related ? candidate : "";
}

const sheetHandle = clean(lead.igHandleFromSheet || "");
const finalHandle = sheetHandle || siteHandle;

return { json: {
  row_number: lead.row_number,
  email: lead.email,
  businessName: lead.businessName,
  adresse: lead.adresse,
  siteWeb: siteWeb,
  igHandle: finalHandle,
  igHandleSource: sheetHandle ? "sheet" : (siteHandle ? "website" : (isAggregator ? "none-aggregator-site" : "none"))
} };

const p = $json;
const bio = p.biography || "";
const cat = p.businessCategoryName || "";
const followers = p.followersCount || "";
let caps = "";
try { caps = (p.latestPosts || []).map(x => x.caption).filter(Boolean).slice(0,6).join(" | "); } catch (e) {}
const ctx = "Source: compte Instagram existant.\nBio: " + bio + "\nCategorie: " + cat + "\nAbonnes: " + followers + "\nCaptions recentes: " + caps;
return { json: { accountContext: ctx, sourceType: "instagram" } };

let html = $json.data || $json.body || "";
if (typeof html !== "string") { html = JSON.stringify(html); }
let text = html.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
text = text.slice(0, 1500);
const site = $("Route Source").item.json.siteWeb || "";
const ctx = text ? ("Source: site web (" + site + ").\nContenu: " + text) : "Source: aucune donnee en ligne. Base-toi sur le nom, le secteur et l adresse de l etablissement.";
return { json: { accountContext: ctx, sourceType: "website" } };

// Accepts output from the SSH/Claude-Code node ($json.stdout) and still tolerates
// the legacy Anthropic-API shape, so nothing breaks if the source is swapped again.
function llmText(j){
  if (typeof j.stdout === 'string' && j.stdout.trim()) return j.stdout;
  if (Array.isArray(j.content)) return j.content.filter(b=>b&&b.type==='text').map(b=>b.text).join('\n');
  return j.output ?? j.text ?? j.content ?? j.response ?? (j.message && j.message.content);
}
let raw = llmText($json);
if (raw===undefined||raw===null||raw==='') raw = JSON.stringify($json);
if (typeof raw==='object') raw = JSON.stringify(raw);
raw = String(raw).trim();
// strip a markdown code fence if the model added one
raw = raw.replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();

let parsed={};
try { parsed = JSON.parse(raw); }
catch(e){ const m = raw.match(/\{[\s\S]*\}/); if(m){ try{ parsed = JSON.parse(m[0]); }catch(e2){ parsed = {parse_error:e2.message}; } } else { parsed = {parse_error:e.message}; } }

let lead;
try { lead = $('Route Source').item.json; } catch (e) { lead = $('Route Source').first().json; }
const biz = (lead.businessName || '').toString();

// Deterministic fallback: if the LLM step failed for any reason the pipeline still
// produces a usable mockup instead of dying.
const fallbackPrompt = 'A vertical 9:16 showcase board of example Instagram post mockups for ' + (biz || 'a local restaurant') + ': a grid of 3 columns by 4 rows of distinct post cards, each a different post type (menu du jour, promotion, event, signature dish, customer review, new item, opening hours, behind-the-scenes, special offer, brunch, drinks happy hour, slogan), each rendered with a cohesive brand palette and a clear readable brand font, with a short headline and a line of descriptive text. Cohesive branded feed, high-end food photography, modern typography, tall portrait 9:16.';

return { json: {
  mockup_prompt: parsed.mockup_prompt || fallbackPrompt,
  feed_theme: parsed.feed_theme || '',
  llm_ok: parsed.mockup_prompt ? true : false,
  feedDetailsJson: JSON.stringify(parsed, null, 2)
} };

