const biz = rawBiz.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'lead';
const ts = new Date().toISOString().replace(/[^0-9]/g, '').slice(0, 14);
